  { id: 'sign',   label: 'SIGN: OS',             fn: cycleSign },
  { id: 'pca',    label: 'PCA ANALYSIS',         fn: togglePCA },
  { id: 'hmode',  label: 'HIST: LOG',            fn: cycleHistMode },
  { id: 'fitm',   label: 'FIT WIN -',            fn: function () { stepFit(-1); }, hidden: true },
  { id: 'fitp',   label: 'FIT WIN +',            fn: function () { stepFit(1); },  hidden: true },
  { id: 'clrbin', label: 'CLEAR BIN',            fn: clearBin, hidden: true },
