  { id: 'hull',   label: '\u2B21 2D ENVELOPE',   fn: toggleHull2D },
  { id: 'envp',   label: 'ENV: P99',             fn: cycleEnv },
  { id: 'obj',    label: '\u25C6 DRAW 3D OBJECT', fn: toggleObject },
