];
function sizeBtn(def) {
  def.w = Math.ceil(def.label.length * 7.6 + 28);
  def.r.setAttribute('width', def.w);
  def.t.setAttribute('x', def.w / 2); def.t.textContent = def.label;
}
BTNS.forEach(function (def) {
  var g = document.createElementNS(SVGNS, 'g'); g.setAttribute('class', 'btn');
  var r = document.createElementNS(SVGNS, 'rect'), t = document.createElementNS(SVGNS, 'text');
  r.setAttribute('height', 30); t.setAttribute('y', 19);
  g.appendChild(r); g.appendChild(t);
  def.r = r; def.t = t; def.g = g; sizeBtn(def);
  g.addEventListener('click', def.fn);
  if (def.hidden) g.setAttribute('display', 'none');
  uiBtns.appendChild(g);
});
function btn(id) { for (var i = 0; i < BTNS.length; i++) if (BTNS[i].id === id) return BTNS[i]; }
function setActive(id, on) { btn(id).g.classList.toggle('active', !!on); }
function setHidden(id, hid) { var b = btn(id); b.hidden = hid; b.g.setAttribute('display', hid ? 'none' : 'inline'); }
function relabel(id, text) { var b = btn(id); if (b.label !== text) { b.label = text; sizeBtn(b); } }
function histLinear() { return !HMODES[histMode].log; }
function syncButtons() {
  setActive('hull', showHull); setActive('obj', objOn); setActive('spin', autoRotate);
  setActive('scan', scanMode); setActive('key', showLegend); setActive('col', colorMode !== 0);
  setActive('pca', pcaMode);
  setHidden('next', !scanMode);
  setHidden('fitm', !histLinear()); setHidden('fitp', !histLinear());
  setHidden('clrbin', !binSel);
  relabel('col', 'COLOR: ' + COLOR_NAMES[colorMode]);
  relabel('sign', 'SIGN: ' + SIGN_NAMES[signMode]);
  relabel('hmode', 'HIST: ' + HMODES[histMode].name);
  relabel('envp', 'ENV: ' + (envPct >= 100 ? 'MAX' : 'P' + envPct));
  layoutButtons();
}

$('zoom-in').addEventListener('click',  function () { targetZoom = Math.min(ZOOM_MAX, targetZoom * ZOOM_STEP); });
$('zoom-out').addEventListener('click', function () { targetZoom = Math.max(ZOOM_MIN, targetZoom / ZOOM_STEP); });

function setStatus(a, b, c) { stEl[0].textContent = a || ''; stEl[1].textContent = b || ''; stEl[2].textContent = c || ''; }
function fmt(v) { return v.toExponential(2).toUpperCase(); }
function mfmt(m) { return m.toFixed(m < 10 ? 3 : 2); }
function selSummary() {
  var t = 'SIGN ' + SIGN_NAMES[signMode];
  if (cutPt > 0) t += '  PT>=' + cutPt.toFixed(1);
  if (isFinite(cutEta)) t += '  |ETA|<=' + cutEta.toFixed(1);
  if (binSel) t += '  M ' + mfmt(binSel.lo) + '-' + mfmt(binSel.hi);
  return t;
}
function updateStats() {
  var ne = events.length, nv = px.length, ns = vev.length;
  sxEl[0].textContent = ne ? ('EVENTS ' + ns + ' / ' + ne + '  VECTORS ' + nv + (dataLabel ? '  [' + dataLabel + ']' : '')) : '';
  sxEl[1].textContent = ne ? ('MAX |P| ' + maxNorm.toFixed(1) + ' GEV   ' + selSummary()) : '';
  if (!ne) sxEl[2].textContent = '';
  else if (scanMode) sxEl[2].textContent = 'SCAN VIEW: EVENTS ' + sliceStart + ' TO ' + Math.min(sliceStart + MAX_SCAN, ns) + ' OF ' + ns;
  else sxEl[2].textContent = lodStride > 1 ? ('DRAWING 1 IN ' + lodStride + ' VECTORS WHILE MOVING (PRESS SPIN TO PAUSE: FULL DENSITY)') : 'DRAWING ALL VECTORS';
  sxEl[3].textContent = HULL ? ('ENVELOPE ' + (HULL.pct >= 100 ? 'MAX' : 'P' + HULL.pct) + ' OF SELECTION  VERTICES ' + HULL.nV + '  EDGES ' + HULL.nE + '  FACES ' + HULL.nF + '  (' + hullMs.toFixed(0) + ' MS)') : '';
  sxEl[4].textContent = HULL ? ('ENVELOPE VOLUME ' + fmt(HULL.vol) + ' GEV\u00B3   SURFACE ' + fmt(HULL.area) + ' GEV\u00B2') : '';
  cutsTitle.textContent = (ne && histData) ? ('CUTS (BOTH MUONS)  ' + histData.nPass + '/' + ne + ' PASS') : 'CUTS (BOTH MUONS)';
}

/* ---------- layout ---------- */
var infoTop = 100;
function layoutButtons() {
  var x0 = -W / 2 + 20, x = x0, y = -H_ / 2 + 20, maxX = W / 2 - 90;
  BTNS.forEach(function (def) {
    if (def.hidden) return;
    if (x + def.w > maxX && x > x0) { x = x0; y += 38; }
    def.g.setAttribute('transform', 'translate(' + x + ',' + y + ')');
    x += def.w + 8;
  });
  var sy = y + 52;
  stEl.forEach(function (e, i) { e.setAttribute('x', x0); e.setAttribute('y', sy + i * 15); });
  var cutsTop = sy + 3 * 15 + 6;
  cutsG.setAttribute('transform', 'translate(' + (x0 - 8) + ',' + cutsTop + ')');
  infoTop = cutsTop + CUTS_H + 6;
  infoBg.setAttribute('x', x0 - 8); infoBg.setAttribute('y', infoTop);
  infEl.forEach(function (e, i) { e.setAttribute('x', x0); e.setAttribute('y', infoTop + 17 + i * 13); });
}
function updateVisibility() {
  var big = W >= 760 && H_ >= 560;
  if (pcaMode) {
    legendGroup.setAttribute('display', 'none');
    histGroup.setAttribute('display', 'none');
  } else {
