var histReady = false;
function layout() {
  var r = svg.getBoundingClientRect();
  W = r.width || window.innerWidth; H_ = r.height || window.innerHeight;
  svg.setAttribute('viewBox', (-W / 2) + ' ' + (-H_ / 2) + ' ' + W + ' ' + H_);
  [bg, vig, scan].forEach(function (e) {
    e.setAttribute('x', -W / 2); e.setAttribute('y', -H_ / 2); e.setAttribute('width', W); e.setAttribute('height', H_);
  });
  K = Math.min(W, H_) / 1300;
