  legendGroup.setAttribute('transform', 'translate(' + (W / 2 - 216) + ',' + (-H_ / 2 + 140) + ')');
  histGroup.setAttribute('transform', 'translate(' + (W / 2 - 340) + ',' + (H_ / 2 - 258) + ')');
  /* PCA panel: left side, below the cuts/info area */
  var pcaTopY = -H_ / 2 + 200;
