window.addEventListener('resize', layout);

/* ---------- interaction ---------- */
var ptrs = new Map(), pinchDist = 0;
function pdist() { var a = Array.from(ptrs.values()); return Math.hypot(a[0].x - a[1].x, a[0].y - a[1].y); }
svg.addEventListener('pointerdown', function (e) {
  if (e.target.closest && e.target.closest('.btn,.hit,.slider-hit')) return;
  ptrs.set(e.pointerId, { x: e.clientX, y: e.clientY, moved: 0 });
  if (autoRotate) { autoRotate = false; syncButtons(); }
  try { svg.setPointerCapture(e.pointerId); } catch (_) {}
  if (ptrs.size === 2) pinchDist = pdist();
});
svg.addEventListener('pointermove', function (e) {
  var p = ptrs.get(e.pointerId); if (!p) return;
  var dx = e.clientX - p.x, dy = e.clientY - p.y;
  p.x = e.clientX; p.y = e.clientY; p.moved += Math.abs(dx) + Math.abs(dy);
  if (ptrs.size === 1) {
    rotY += dx * 0.005; rotX += dy * 0.005;
    rotX = Math.max(0.05, Math.min(Math.PI / 2.1, rotX));
  } else if (ptrs.size === 2) {
    var nd = pdist();
    if (pinchDist > 0) targetZoom = Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, targetZoom * nd / pinchDist));
    pinchDist = nd;
  }
});
