svg.addEventListener('pointerup', function (e) {
  var p = ptrs.get(e.pointerId);
  var wasClick = p && ptrs.size === 1 && p.moved < 6;
  endPtr(e);
  if (wasClick && scanMode) pick(e);
});
svg.addEventListener('pointercancel', endPtr);
svg.addEventListener('wheel', function (ev) {
  ev.preventDefault();
  targetZoom = Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, targetZoom * (ev.deltaY < 0 ? 1.1 : 1 / 1.1)));
}, { passive: false });
svg.addEventListener('dragover', function (e) { e.preventDefault(); });
svg.addEventListener('drop', function (e) {
  e.preventDefault();
  var f = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
  if (f) readFile(f);
});

/* ---------- modes ---------- */
function toggleLegend() { showLegend = !showLegend; updateVisibility(); syncButtons(); }
function cycleColor() { colorMode = (colorMode + 1) % 3; applyColorMode(); lastKey = ''; syncButtons(); }
function toggleScanMode() {
  scanMode = !scanMode;
  if (scanMode) {
    autoRotate = false;
    setStatus('STATUS: SCAN MODE', 'CLICK A MUON TO INSPECT ITS PAIR', events.length ? '' : 'LOAD DATA OR PRESS DEMO FIRST');
  } else {
    clearSel();
    setStatus('STATUS: FREE ROAM', '');
  }
  lastKey = ''; syncButtons(); updateStats();
}
function nextSlice() {
  if (!vev.length) return;
  sliceStart += MAX_SCAN;
  if (sliceStart >= vev.length) sliceStart = 0;
  clearSel(); lastKey = ''; updateStats();
}
function toggleHull2D() {
  showHull = !showHull; syncButtons();
  if (showHull) withHull(function () { objDirty = true; }); else objDirty = true;
}

/* ---------- colour buckets ---------- */
var BP = [];
(function () {
  for (var k = 0; k < 24; k++) {
    var p = document.createElementNS(SVGNS, 'path');
    p.setAttribute('vector-effect', 'non-scaling-stroke');
    bucketGroup.appendChild(p); BP.push(p);
  }
})();
function applyColorMode() {
  var k;
  for (k = 0; k < 24; k++) {
    if (colorMode === 1) BP[k].setAttribute('stroke', k < 5 ? MASS_COL[k] : '#000');
    else BP[k].setAttribute('stroke', 'hsl(' + ((k * 137.5) % 360).toFixed(0) + ',80%,60%)');
    BP[k].setAttribute('d', '');
  }
  var heat = colorMode === 0;
  bucketGroup.setAttribute('display', heat ? 'none' : 'inline');
  vectorPath.setAttribute('display', heat ? 'inline' : 'none');
  vectorBloom.setAttribute('display', (heat && !heavyData) ? 'inline' : 'none');
}
function massBucket(m) {
  if (m === null || !isFinite(m)) return 4;
  if (m < 10) return 0; if (m < 80) return 1; if (m < 100) return 2; return 3;
}

/* ---------- data ---------- */
/* events = everything loaded. vev = the events that pass sign + cuts + isolated bin.
   px/py/pz/vecStart/bMass/bPair are the display arrays, always rebuilt from vev. */
function etaOf(v) {
  var pt = Math.sqrt(v[0] * v[0] + v[1] * v[1]);
  if (pt < 1e-9) return v[2] >= 0 ? 99 : -99;
  var t = v[2] / pt;
  return Math.log(t + Math.sqrt(t * t + 1));
}

/* Charge-flip rate (CFR): single-muon charge mis-identification probability.
