   low pT, rising to a few percent in the endcap at high pT. NOT a measurement --
   only for visualizing how much of the observed same-sign sample is expected
   to come from charge flips of opposite-sign pairs. Replace this with a
   tag-and-probe result before using for any real measurement. */
function chargeFlipRate(pt, eta) {
  if (!isFinite(pt) || !isFinite(eta) || pt < 0) return 0;
  var ptFactor = pt < 50 ? 0.001 : 0.001 + (pt - 50) / 200 * 0.05;   // 0.1% -> ~5% at 200 GeV
  var a = Math.abs(eta);
