}
function resetData() {
  events = []; vev = []; px = []; py = []; pz = []; vecStart = []; bMass = []; bPair = [];
  maxMomentum = 0; maxNorm = 0; dataMax = 0; sliceStart = 0;
  HULL = null; hullStale = true; selEv = -1; selDirty = true; lastKey = ''; objDirty = true;
  binSel = null; histData = null; zoomBeforeBin = null;
  PCA = null; pcaStale = true;
  drawHistogram(); syncButtons();
}
function vs(i) { return i < vecStart.length ? vecStart[i] : px.length; }
function applyQuality() {
  // very large files: no glow filters (they re-run over every vector on every repaint)
  heavyData = px.length > MAX_DRAW;
