  ev.pt1 = Math.sqrt(ev.p1[0] * ev.p1[0] + ev.p1[1] * ev.p1[1]); ev.eta1 = etaOf(ev.p1);
  if (ev.p2) { ev.pt2 = Math.sqrt(ev.p2[0] * ev.p2[0] + ev.p2[1] * ev.p2[1]); ev.eta2 = etaOf(ev.p2); }
  ev.ss = (ev.p2 && ev.q1 && ev.q2) ? ((ev.q1 > 0) === (ev.q2 > 0)) : null;   // true = same sign, false = opposite, null = unknown
  for (var j = 0; j < 3; j++) {
