/* selection */
function passCuts(ev) {
  if (ev.pt1 < cutPt || Math.abs(ev.eta1) > cutEta) return false;
  if (ev.p2 && (ev.pt2 < cutPt || Math.abs(ev.eta2) > cutEta)) return false;
