function rebuildView() {
  var i, ev, bm, bp;
  vev = []; px = []; py = []; pz = []; vecStart = []; bMass = []; bPair = [];
  maxMomentum = 0; maxNorm = 0;
  for (i = 0; i < events.length; i++) {
    ev = events[i];
    if (!passCuts(ev) || !passSign(ev) || !passBin(ev)) continue;
    bm = massBucket(ev.mass); bp = ev.i % 24;              // colours stay tied to the original event number
    vecStart.push(px.length);
    addVec(ev.p1[0], ev.p1[1], ev.p1[2]); bMass.push(bm); bPair.push(bp);
    if (ev.p2) { addVec(ev.p2[0], ev.p2[1], ev.p2[2]); bMass.push(bm); bPair.push(bp); }
    vev.push(ev);
  }
  vecStart.push(px.length);
  if (sliceStart >= vev.length) sliceStart = 0;
