  rebuildView();
  clearSel(); syncButtons();
  /* charge-column validation: J/psi must be dominantly OS in real data */
  var cv = validateCharges();
  if (cv.os >= 20 && !cv.ok) {
    setStatus('STATUS: WARNING \u2014 CHARGES LOOK BAD',
      'J/PSI WINDOW SS/OS = ' + (cv.ratio * 100).toFixed(1) + '% (EXPECT < 5%)',
      'SS-BASED BACKGROUND MAY BE UNTRUSTWORTHY. CHECK Q1/Q2 COLUMNS.');
  }
  if (objOn) { objOn = false; toggleObject(); }
  else if (showHull) withHull(function () { objDirty = true; });
}

function pairMass(a, b, E1, E2) {
  if (!b) return null;
  var mm = 0.10566;
  var e1 = isFinite(E1) ? E1 : Math.sqrt(a[0]*a[0] + a[1]*a[1] + a[2]*a[2] + mm*mm);
  var e2 = isFinite(E2) ? E2 : Math.sqrt(b[0]*b[0] + b[1]*b[1] + b[2]*b[2] + mm*mm);
  var sx = a[0] + b[0], sy = a[1] + b[1], sz = a[2] + b[2], et = e1 + e2;
  var m2 = et * et - (sx*sx + sy*sy + sz*sz);
  return m2 > 0 ? Math.sqrt(m2) : null;
}
function parseCERNData(text, label, token) {
  setStatus('STATUS: PARSING DATA...', '', '');
  resetData(); loading = true;
  var lines = text.replace(/^\uFEFF/, '').replace(/\r\n?/g, '\n').split('\n');
  var li = 0; while (li < lines.length && !lines[li].trim()) li++;
  if (li >= lines.length) { setStatus('STATUS: EMPTY FILE'); finishLoad(''); return; }
  var first = lines[li].trim().split(SPLIT);
  var i = (first.length > 4 && isFinite(parseFloat(first[4]))) ? li : li + 1;
  var total = lines.length, skipped = 0, massFromFile = 0, CHUNK = 4000, nextRebuild = 0;

  function step() {
    if (token !== loadToken) return;               // a newer load replaced this one
    try {
      var end = Math.min(total, i + CHUNK);
      for (; i < end; i++) {
        var ln = lines[i].trim(); if (!ln) continue;
        var p = ln.split(SPLIT);
        if (p.length < 16) { skipped++; continue; }
        var v1 = [parseFloat(p[4]), parseFloat(p[5]), parseFloat(p[6])];
        var v2 = [parseFloat(p[13]), parseFloat(p[14]), parseFloat(p[15])];
        var ok1 = isFinite(v1[0]) && isFinite(v1[1]) && isFinite(v1[2]);
        var ok2 = isFinite(v2[0]) && isFinite(v2[1]) && isFinite(v2[2]);
        if (!ok1 && !ok2) { skipped++; continue; }
        var mFile = p.length > 20 ? parseFloat(p[20]) : NaN, mass;
        if (isFinite(mFile)) { mass = mFile; massFromFile++; }
        else mass = (ok1 && ok2) ? pairMass(v1, v2, parseFloat(p[3]), parseFloat(p[12])) : null;
        var t1 = (p[2] || '').toUpperCase(), t2 = (p[11] || '').toUpperCase();
        var Q1 = parseFloat(p[10]), Q2 = parseFloat(p[19]);      // CMS dimuon columns Q1 and Q2
        addEvent({
          run: p[0], id: p[1] || ('E' + i), mass: mass,
          p1: ok1 ? v1 : v2, t1: ok1 ? t1 : t2, q1: ok1 ? Q1 : Q2,
          p2: (ok1 && ok2) ? v2 : null, t2: t2, q2: Q2
        });
      }
      if (i < total) {
        if (events.length >= nextRebuild) { rebuildView(); nextRebuild = Math.floor(events.length * 1.5) + 5000; }
        setStatus('STATUS: PARSING DATA...', events.length + ' EVENTS  (' + Math.round(i / total * 100) + '%)', '');
        setTimeout(step, 0); return;
      }
      if (!events.length) { setStatus('STATUS: NO VALID DATA', 'CHECK COLUMNS 5-7 AND 14-16'); finishLoad(''); return; }
      setStatus('STATUS: LOADED', events.length + ' DIMUON EVENTS',
        (skipped ? 'SKIPPED ' + skipped + ' ROWS. ' : '') + 'PAIR MASS FROM FILE: ' + massFromFile + '/' + events.length + ' (REST COMPUTED)');
      finishLoad(label);
    } catch (err) {
      console.error(err); setStatus('STATUS: PARSE ERROR', String(err && err.message || err), '');
      finishLoad(events.length ? label : '');
    }
  }
