}
function abortAuto() { if (autoAbort) { try { autoAbort.abort(); } catch (_) {} autoAbort = null; } }
function readFile(file) {
  var token = ++loadToken; abortAuto();
  setStatus('STATUS: READING FILE...', file.name, '');
  var reader = new FileReader();
  reader.onerror = function () { if (token === loadToken) setStatus('STATUS: READ ERROR'); };
  reader.onload = function (ev) {
    if (token !== loadToken) return;
    try { parseCERNData(ev.target.result, file.name.toUpperCase().slice(0, 20), token); }
    catch (err) { console.error(err); setStatus('STATUS: PARSE ERROR'); }
  };
  reader.readAsText(file);
}
fileInput.addEventListener('change', function (e) {
  var f = e.target.files[0]; if (f) readFile(f); fileInput.value = '';
});

/* ---------- AUTO LOADER: downloads the CMS 2010B dimuon file, then parses it ---------- */
function autoLoad() {
  var token = ++loadToken; abortAuto();
  var stale = function () { return token !== loadToken; };
  var fail = function (err) {
    if (stale()) return;
    console.error(err);
    setStatus('STATUS: AUTO LOAD FAILED', String(err && err.message || err),
      'USE LOAD CSV, DROP A FILE, OR PRESS DEMO DATA');
  };
  if (typeof fetch !== 'function') { fail(new Error('FETCH NOT SUPPORTED')); return; }
  setStatus('STATUS: AUTO LOAD', 'CONNECTING: ' + AUTO_URL.replace(/^https?:\/\//, ''), '');
  var opts = { mode: 'cors', credentials: 'omit' };
  if (typeof AbortController === 'function') { autoAbort = new AbortController(); opts.signal = autoAbort.signal; }
  fetch(AUTO_URL, opts).then(function (resp) {
    if (!resp.ok) throw new Error('HTTP ' + resp.status);
    var total = parseInt(resp.headers.get('content-length'), 10) || 0;
    if (!resp.body || !resp.body.getReader || typeof TextDecoder !== 'function') return resp.text();
    var reader = resp.body.getReader(), dec = new TextDecoder('utf-8'), parts = [], got = 0;
    function pump() {
      return reader.read().then(function (r) {
        if (stale()) { try { reader.cancel(); } catch (_) {} return ''; }
        if (r.done) { parts.push(dec.decode()); return parts.join(''); }
        got += r.value.length; parts.push(dec.decode(r.value, { stream: true }));
        setStatus('STATUS: AUTO LOAD',
          'DOWNLOADING ' + (got / 1048576).toFixed(1) + ' MB' +
          (total ? ' / ' + (total / 1048576).toFixed(1) + ' MB (' + Math.min(100, Math.round(got / total * 100)) + '%)' : ''), '');
        return pump();
      });
    }
    return pump();
  }).then(function (text) {
    if (stale()) return;
    autoAbort = null;
    if (!text || !text.trim()) throw new Error('SERVER RETURNED NO DATA');
    parseCERNData(text, AUTO_LABEL, token);
  }).catch(function (err) {
    if (err && err.name === 'AbortError') return;
    fail(err);
  });
}

/* Synthetic dimuon-like events (J/psi, Upsilon, Z + continuum). Muons come from a real two-body decay,
   so the stored pair mass equals the invariant mass of the two vectors. NOT real CERN data. */
function loadDemo() {
  ++loadToken; abortAuto();
  var s = 2010 >>> 0;
  function rnd() { s = (s + 0x6D2B79F5) >>> 0; var t = s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }
  function gauss() { return Math.sqrt(-2 * Math.log(1 - rnd())) * Math.cos(2 * Math.PI * rnd()); }
  resetData();
  for (var i = 0; i < 4000; i++) {
    var r = rnd(), M;
    if (r < 0.12) M = 3.097 + 0.05 * gauss();
    else if (r < 0.20) M = 9.46 + 0.25 * gauss();
    else if (r < 0.45) M = 91.19 + 2.5 * gauss();
    else M = 2 - Math.log(1 - rnd()) * 12;
    M = Math.max(M, 1.5);
    var pT = Math.min(150, -Math.log(1 - rnd()) * (6 + M * 0.12)), yy = Math.max(-2.4, Math.min(2.4, gauss() * 1.1)), ph = 2 * Math.PI * rnd();
    var mT = Math.sqrt(M * M + pT * pT);
    var Px = pT * Math.cos(ph), Py = pT * Math.sin(ph), Pz = mT * Math.sinh(yy), E = mT * Math.cosh(yy);
    var ct = 2 * rnd() - 1, st = Math.sqrt(1 - ct * ct), ph2 = 2 * Math.PI * rnd(), ps = M / 2;
    var qx = ps * st * Math.cos(ph2), qy = ps * st * Math.sin(ph2), qz = ps * ct, Es = M / 2;
    var bx = Px / E, by = Py / E, bz = Pz / E, b2 = bx*bx + by*by + bz*bz, g = E / M;
    var bp = bx*qx + by*qy + bz*qz;
    var k1 = 0, k2 = 0;
    if (b2 > 1e-12) { k1 = (g - 1) * bp / b2 + g * Es; k2 = (g - 1) * (-bp) / b2 + g * Es; }
    var q1 = rnd() < 0.5 ? 1 : -1, ssPair = r >= 0.45 && rnd() < 0.25, q2 = ssPair ? q1 : -q1;   // resonances are opposite-sign; 25% of continuum is same-sign
    addEvent({
      run: 'DEMO', id: String(i), mass: M, t1: 'G', t2: 'G', q1: q1, q2: q2,
      p1: [qx + k1*bx, qy + k1*by, qz + k1*bz],
      p2: [-qx + k2*bx, -qy + k2*by, -qz + k2*bz]
    });
  }
  setStatus('STATUS: DEMO LOADED', events.length + ' SYNTHETIC EVENTS, NOT CERN DATA', 'MUON CHARGES ARE SIMULATED: RESONANCES OS, 25% OF CONTINUUM SS');
  finishLoad('SYNTHETIC DEMO');
}

/* ---------- histogram: counts axis, OS/SS, J/psi fit window, clickable bins ---------- */
function clearChildren(el) { while (el.firstChild) el.removeChild(el.firstChild); }
function niceStep(v, n) {
  var raw = v / n, p = Math.pow(10, Math.floor(Math.log10(raw))), f = raw / p;
  return (f <= 1 ? 1 : f <= 2 ? 2 : f <= 5 ? 5 : 10) * p;
}
function fmtCount(v) { return v >= 10000 ? (v / 1000).toFixed(v % 1000 ? 1 : 0) + 'k' : String(Math.round(v)); }

function computeHist() {
  var sp = HMODES[histMode], nb = sp.nb, lo = sp.log ? LOG_MIN : sp.lo, hi = sp.log ? LOG_MAX : sp.hi;
  var os = new Array(nb).fill(0), ss = new Array(nb).fill(0), un = new Array(nb).fill(0), flip = new Array(nb).fill(0), nPass = 0;
  var i, ev, m, u, b;
  for (i = 0; i < events.length; i++) {
    ev = events[i];
    if (!passCuts(ev)) continue;
    nPass++;
    m = ev.mass; if (m === null || !(m > 0)) continue;
    u = sp.log ? Math.log10(m) : m;
    if (u < lo || u >= hi) continue;
    b = Math.min(nb - 1, Math.floor((u - lo) / (hi - lo) * nb));
    if (ev.ss === false) { os[b]++; if (ev.p2) flip[b] += pairFlipProb(ev); }
    else if (ev.ss === true) ss[b]++;
    else un[b]++;
  }
  histData = { sp: sp, nb: nb, lo: lo, hi: hi, os: os, ss: ss, un: un, flip: flip, nPass: nPass };
}
function histSeries(hd) {
  var out = [], i;
  for (i = 0; i < hd.nb; i++) out.push(signMode === 0 ? hd.os[i] : signMode === 1 ? hd.ss[i] : hd.os[i] + hd.ss[i] + hd.un[i]);
  return out;
}
function binRange(hd, q) {
  var a = hd.lo + q * (hd.hi - hd.lo) / hd.nb, b = hd.lo + (q + 1) * (hd.hi - hd.lo) / hd.nb;
  return hd.sp.log ? [Math.pow(10, a), Math.pow(10, b)] : [a, b];
}
function massToX(m) {
  var hd = histData;
  if (!hd || !(m > 0)) return null;
  var u = hd.sp.log ? Math.log10(m) : m;
  if (u < hd.lo || u > hd.hi) return null;
  return HP.L + (u - hd.lo) / (hd.hi - hd.lo) * (HP.R - HP.L);
}
function subDefault() {
  if (binSel && binSel.mode === histMode) return 'ISOLATED ' + mfmt(binSel.lo) + '-' + mfmt(binSel.hi) + ' GEV. CLICK THE BIN AGAIN TO CLEAR';
  return 'CLICK A BIN TO SHOW ONLY ITS EVENTS IN 3D';
}
function hoverBin(q) {
  if (!histSub || !histData) return;
  if (q < 0) { histSub.textContent = subDefault(); return; }
  var r = binRange(histData, q);
  histSub.textContent = 'BIN ' + mfmt(r[0]) + '-' + mfmt(r[1]) + ' GEV: ' + histSeries(histData)[q] + ' EVENTS';
}

function drawHistogram() {
  clearChildren(histBody); histMarker.setAttribute('display', 'none'); histSub = null;
  var hd = histData;
  histReady = !!(hd && events.length);
  if (!histReady) { updateVisibility(); return; }

  var sp = hd.sp, nb = hd.nb, L = HP.L, R = HP.R, T = HP.T, B = HP.B, barW = (R - L) / nb, i;
  var main = histSeries(hd), over = signMode === 0 ? hd.ss : null, ymax = 0;
  for (i = 0; i < nb; i++) {
    if (main[i] > ymax) ymax = main[i];
    if (over && over[i] > ymax) ymax = over[i];
    if (hd.flip && hd.flip[i] > ymax) ymax = hd.flip[i];
  }
  var ystep = Math.max(1, niceStep(Math.max(1, ymax) * 1.05, 4));
  var ytop = Math.max(ystep, Math.ceil(Math.max(1, ymax) * 1.05 / ystep) * ystep);
  function yOf(c) { return B - Math.min(c, ytop) / ytop * (B - T); }
  function xOf(u) { return L + (u - hd.lo) / (hd.hi - hd.lo) * (R - L); }

  mk('text', { class: 'legend-text legend-hl', x: 10, y: 14 }, histBody,
     'INVARIANT MASS \u00B7 ' + SIGN_NAMES[signMode] + (sp.log ? ' \u00B7 LOG X' : ' \u00B7 LINEAR X'));
  mk('text', { class: 'hist-text', x: R, y: 14, 'text-anchor': 'end', style: 'fill:#ff44cc' }, histBody, '\u2014 OBS SS');
  mk('text', { class: 'hist-text', x: R, y: 25, 'text-anchor': 'end', style: 'fill:#ffaa00' }, histBody, '-- PRED SS (FLIPS)');
  histSub = mk('text', { class: 'hist-text', x: 10, y: 27 }, histBody, subDefault());

  // counts axis + grid
  mk('line', { class: 'hist-axis', x1: L, y1: T, x2: L, y2: B }, histBody);
  mk('line', { class: 'hist-axis', x1: L, y1: B, x2: R, y2: B }, histBody);
  mk('text', { class: 'hist-text', x: L - 4, y: T - 5, 'text-anchor': 'end' }, histBody, 'COUNTS');
  for (var t = 0; t <= ytop + 1e-9; t += ystep) {
    var yy = yOf(t);
    if (t > 0) mk('line', { class: 'hist-grid', x1: L, y1: yy, x2: R, y2: yy }, histBody);
    mk('text', { class: 'hist-text', x: L - 4, y: yy + 3, 'text-anchor': 'end' }, histBody, fmtCount(t));
  }

  // mass axis
  var lines = ['', '', ''], fitInfo = null, wlo = 0, whi = 0;
  if (sp.log) {
    [0.1, 1, 10, 100].forEach(function (v) {
      var x = xOf(Math.log10(v));
      mk('line', { class: 'hist-axis', x1: x, y1: B, x2: x, y2: B + 3 }, histBody);
      mk('text', { class: 'hist-text', x: x, y: B + 12, 'text-anchor': 'middle' }, histBody, String(v));
    });
  } else {
    var xs = niceStep(hd.hi - hd.lo, 5), dec = Math.max(0, -Math.floor(Math.log10(xs) + 1e-9));
    for (var xv = Math.ceil(hd.lo / xs - 1e-9) * xs; xv <= hd.hi + 1e-9; xv += xs) {
      var xt = xOf(xv);
      mk('line', { class: 'hist-axis', x1: xt, y1: B, x2: xt, y2: B + 3 }, histBody);
      mk('text', { class: 'hist-text', x: xt, y: B + 12, 'text-anchor': 'middle' }, histBody, xv.toFixed(dec));
    }
  }
  mk('text', { class: 'hist-text', x: (L + R) / 2, y: B + 23, 'text-anchor': 'middle' }, histBody, 'M(\u03BC\u03BC) [GEV]');

  // fit window (drawn under the bars)
  var bw = (hd.hi - hd.lo) / nb, fxs = [], fys = [], tot = 0;
  if (!sp.log && sp.peak) {
    wlo = Math.max(hd.lo, sp.peak - fitHalf); whi = Math.min(hd.hi, sp.peak + fitHalf);
    mk('rect', { class: 'hist-win', x: xOf(wlo), y: T, width: xOf(whi) - xOf(wlo), height: B - T }, histBody);
    [wlo, whi].forEach(function (u) {
      mk('line', { x1: xOf(u), y1: T, x2: xOf(u), y2: B, stroke: '#ffcc00', 'stroke-width': 1, 'stroke-dasharray': '3 2', opacity: 0.7, 'pointer-events': 'none' }, histBody);
    });
    for (i = 0; i < nb; i++) {
      var cx = hd.lo + (i + 0.5) * bw;
      if (cx >= wlo && cx <= whi) { fxs.push(cx); fys.push(main[i]); tot += main[i]; }
    }
    if (tot >= 20) fitInfo = fitGaussBkg(fxs, fys, sp.peak, bw);
  }

  // bars
  for (i = 0; i < nb; i++) {
    if (!main[i]) continue;
    var yb = yOf(main[i]);
    var cls = 'hist-bar' + (signMode === 1 ? ' ss' : '') + ((binSel && binSel.mode === histMode && binSel.q === i) ? ' sel' : '');
    mk('rect', { class: cls, x: (L + i * barW).toFixed(1), y: yb.toFixed(1), width: Math.max(0.5, barW - 0.6).toFixed(1), height: (B - yb).toFixed(1) }, histBody);
  }
  // same-sign outline = observed SS sample (combinatorial + charge-flip background)
  if (over) {
    var od = '';
    for (i = 0; i < nb; i++) {
      var x0 = L + i * barW, x1 = x0 + barW, y0 = yOf(over[i]);
      od += (i ? 'L' : 'M') + x0.toFixed(1) + ',' + y0.toFixed(1) + 'L' + x1.toFixed(1) + ',' + y0.toFixed(1);
    }
    mk('path', { class: 'hist-over', d: od }, histBody);
  }
  // charge-flip prediction: how much of the observed SS sample is expected from OS charge mis-ID
  if (hd.flip) {
    var fd = '';
    for (i = 0; i < nb; i++) {
      var fx0 = L + i * barW, fx1 = fx0 + barW, fy0 = yOf(hd.flip[i]);
      fd += (i ? 'L' : 'M') + fx0.toFixed(1) + ',' + fy0.toFixed(1) + 'L' + fx1.toFixed(1) + ',' + fy0.toFixed(1);
    }
    mk('path', { d: fd, fill: 'none', stroke: '#ffaa00', 'stroke-width': 1.4, 'stroke-dasharray': '5 3', opacity: 0.95, 'pointer-events': 'none' }, histBody);
  }

  // resonance markers
  var marks = sp.log ? [{ m: 3.1, l: 'J/\u03C8' }, { m: 9.5, l: '\u03A5' }, { m: 91, l: 'Z' }] : [{ m: sp.peak, l: sp.name }];
  marks.forEach(function (pk) {
    var x = massToX(pk.m);
    if (x === null) return;
    mk('line', { class: 'hist-grid', x1: x, y1: T, x2: x, y2: B }, histBody);
    mk('text', { class: 'hist-text', x: x, y: T - 3, 'text-anchor': 'middle' }, histBody, pk.l);
  });

  // fit curve + results
  if (sp.log) {
    lines[0] = 'PEAKS: J/\u03C8 ~3.1 | \u03A5 ~9.5 | Z ~91 GEV';
    lines[1] = 'ORANGE DASH = SS PREDICTED FROM OS CHARGE FLIPS (PLACEHOLDER CFR)';
    lines[2] = 'PASS CUTS: ' + hd.nPass + ' / ' + events.length + ' EVENTS  |  COUNTS PER LOG BIN';
  } else if (fitInfo) {
    var NS = 90, cd = '', j;
    for (j = 0; j <= NS; j++) {
      var xx = wlo + (whi - wlo) * j / NS;
      cd += (j ? 'L' : 'M') + xOf(xx).toFixed(1) + ',' + yOf(fitInfo.f(xx)).toFixed(1);
    }
    mk('path', { class: 'hist-fit', d: cd }, histBody);
    mk('line', { x1: xOf(wlo), y1: yOf(fitInfo.bg(wlo)), x2: xOf(whi), y2: yOf(fitInfo.bg(whi)), stroke: '#ffcc00', 'stroke-width': 1, 'stroke-dasharray': '4 3', opacity: 0.8, 'pointer-events': 'none' }, histBody);
    lines[0] = 'FIT ' + wlo.toFixed(2) + '-' + whi.toFixed(2) + ' GEV: GAUSS + LINEAR BKG';
    lines[1] = 'MU ' + fitInfo.mu.toFixed(4) + ' +/- ' + fitInfo.err[1].toFixed(4) + '  SIGMA ' + (fitInfo.sigma * 1000).toFixed(1) + ' +/- ' + (fitInfo.err[2] * 1000).toFixed(1) + ' MEV';
    lines[2] = 'N(SIG) ' + Math.round(fitInfo.N) + '  CHI2/NDF ' + fitInfo.chi2.toFixed(1) + '/' + fitInfo.ndf;
    lines[3] = 'ORANGE DASH = PRED SS FROM OS CHARGE FLIPS (NOT SUBTRACTED FROM FIT)';
  } else {
    lines[0] = 'FIT WINDOW ' + wlo.toFixed(2) + '-' + whi.toFixed(2) + ' GEV';
    lines[1] = 'TOO FEW EVENTS IN THE WINDOW TO FIT';
  }
  for (i = 0; i < 4; i++) {
    if (lines[i]) mk('text', { class: 'hist-text', x: 10, y: B + 37 + i * 11, style: 'fill:#ffcc00' }, histBody, lines[i]);
  }

  // one invisible hit rectangle per bin (on top, so clicks land on it)
  for (i = 0; i < nb; i++) (function (q) {
    var h = mk('rect', { class: 'hit', x: (L + q * barW).toFixed(2), y: T, width: barW.toFixed(2), height: B - T }, histBody);
    h.addEventListener('click', function () { onBinClick(q); });
    h.addEventListener('pointerenter', function () { hoverBin(q); });
    h.addEventListener('pointerleave', function () { hoverBin(-1); });
  })(i);
  updateVisibility();
}

function onBinClick(q) {
  var hd = histData;
  if (!hd) return;
  if (binSel && binSel.mode === histMode && binSel.q === q) { clearBin(); return; }
  var r = binRange(hd, q);
  if (!binSel) zoomBeforeBin = targetZoom;
  binSel = { q: q, mode: histMode, lo: r[0], hi: r[1] };
  drawHistogram(); rebuildView(); clearSel(); syncButtons();
  if (px.length) targetZoom = Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, 380 / Math.max(1, maxNorm * scaleFactor())));   // frame the isolated events
  setStatus('STATUS: BIN ISOLATED', 'M = ' + mfmt(r[0]) + ' TO ' + mfmt(r[1]) + ' GEV', vev.length + ' EVENTS SHOWN IN THE 3D VIEW');
}
function clearBin() {
  if (!binSel) return;
  binSel = null;
  if (zoomBeforeBin !== null) { targetZoom = zoomBeforeBin; zoomBeforeBin = null; }
  drawHistogram(); rebuildView(); clearSel(); syncButtons();
  setStatus('STATUS: BIN CLEARED', 'SHOWING ALL EVENTS THAT PASS THE SIGN AND CUTS', '');
}
function cycleSign() {
  signMode = (signMode + 1) % 3;
  drawHistogram(); rebuildView(); clearSel(); syncButtons();
  setStatus('STATUS: SIGN ' + SIGN_NAMES[signMode], signMode === 0 ? 'OPPOSITE-SIGN PAIRS. MAGENTA = OBS SS, ORANGE DASH = PRED SS FROM OS CHARGE FLIPS' : signMode === 1 ? 'SAME-SIGN PAIRS: COMBINATORIAL + CHARGE-FLIP BG (FLIP RATE NOT SUBTRACTED)' : 'ALL PAIRS', '');
}
function cycleHistMode() {
  histMode = (histMode + 1) % HMODES.length;
  if (binSel && zoomBeforeBin !== null) { targetZoom = zoomBeforeBin; zoomBeforeBin = null; }
  binSel = null;
  computeHist(); drawHistogram(); rebuildView(); clearSel(); syncButtons();
}
function stepFit(dir) {
  fitHalf = Math.max(0.10, Math.min(0.50, +(fitHalf + dir * 0.05).toFixed(2)));
  drawHistogram();
}
function cycleEnv() {
  envPct = ENV_PCTS[(ENV_PCTS.indexOf(envPct) + 1) % ENV_PCTS.length];
  syncButtons(); hullStale = true; invalidateHull();
  setStatus('STATUS: ENVELOPE PERCENTILE ' + (envPct >= 100 ? 'MAX (HULL)' : envPct), envPct >= 100 ? 'NO OUTLIER REJECTION' : 'IGNORES THE OUTER ' + (100 - envPct).toFixed(1) + '% ALONG EACH DIRECTION', '');
}

/* pT / eta sliders */
var refreshPending = false;
function scheduleRefresh() {
  if (refreshPending) return;
  refreshPending = true;
  requestAnimationFrame(function () {
    refreshPending = false;
    computeHist(); drawHistogram(); rebuildView(); clearSel(); syncButtons();
    setStatus('STATUS: CUTS UPDATED', vev.length + ' EVENTS SHOWN IN THE 3D VIEW', '');
  });
}
var SLIDERS = [
  { min: 0, max: 40, step: 0.5, dflt: 0, val: 0,
    txt: function (v) { return 'PT MIN ' + v.toFixed(1) + ' GEV'; },
    apply: function (v) { cutPt = v; } },
  { min: 0.2, max: 2.5, step: 0.1, dflt: 2.5, val: 2.5,
    txt: function (v) { return '|ETA| MAX ' + (v >= 2.5 ? 'OFF' : v.toFixed(1)); },
    apply: function (v) { cutEta = v >= 2.5 ? Infinity : v; } }
];
function paintSlider(sl) {
  var x = SL_X0 + (sl.val - sl.min) / (sl.max - sl.min) * (SL_X1 - SL_X0);
  sl.fill.setAttribute('x2', x); sl.knob.setAttribute('cx', x); sl.lab.textContent = sl.txt(sl.val);
}
function sliderMove(sl, e) {
  var r = sl.hit.getBoundingClientRect(), tw = SL_X1 - SL_X0;
  var u = (e.clientX - r.left) / r.width * (tw + 12) - 6;
  var f = Math.max(0, Math.min(1, u / tw));
  var v = sl.min + Math.round(f * (sl.max - sl.min) / sl.step) * sl.step;
  v = Math.max(sl.min, Math.min(sl.max, +v.toFixed(3)));
  if (v !== sl.val) { sl.val = v; paintSlider(sl); sl.apply(v); scheduleRefresh(); }
}
function buildCuts() {
  SLIDERS.forEach(function (sl, idx) {
    var y = 38 + idx * 22;
    sl.lab = mk('text', { class: 'ui-dim', x: 10, y: y + 3 }, cutsG);
    mk('line', { x1: SL_X0, x2: SL_X1, y1: y, y2: y, stroke: '#00ffcc', 'stroke-width': 1, opacity: 0.35, 'pointer-events': 'none' }, cutsG);
    sl.fill = mk('line', { x1: SL_X0, x2: SL_X0, y1: y, y2: y, stroke: '#00ffcc', 'stroke-width': 2, 'pointer-events': 'none' }, cutsG);
    sl.knob = mk('circle', { cy: y, r: 5, fill: '#00ffcc', filter: 'url(#uiGlow)', 'pointer-events': 'none' }, cutsG);
    sl.hit = mk('rect', { class: 'slider-hit', x: SL_X0 - 6, y: y - 10, width: SL_X1 - SL_X0 + 12, height: 20 }, cutsG);
    sl.drag = false;
    sl.hit.addEventListener('pointerdown', function (e) {
      e.preventDefault(); sl.drag = true;
      try { sl.hit.setPointerCapture(e.pointerId); } catch (_) {}
      sliderMove(sl, e);
    });
    sl.hit.addEventListener('pointermove', function (e) { if (sl.drag) sliderMove(sl, e); });
    var end = function (e) { sl.drag = false; try { sl.hit.releasePointerCapture(e.pointerId); } catch (_) {} };
    sl.hit.addEventListener('pointerup', end); sl.hit.addEventListener('pointercancel', end);
    sl.hit.addEventListener('dblclick', function () { sl.val = sl.dflt; paintSlider(sl); sl.apply(sl.val); scheduleRefresh(); });
    paintSlider(sl);
  });
}

/* ---------- scan-mode picking ---------- */
function clearSel() {
  selEv = -1; selDirty = true;
  infoBg.setAttribute('display', 'none');
  infEl.forEach(function (e) { e.textContent = ''; });
  histMarker.setAttribute('display', 'none');
}
function qtxt(q) { return q > 0 ? '+' : q < 0 ? '-' : '?'; }
function vtxt(label, v, type, q) {
  var mag = Math.sqrt(v[0]*v[0] + v[1]*v[1] + v[2]*v[2]), pt = Math.sqrt(v[0]*v[0] + v[1]*v[1]);
  return [label + ' [TYPE ' + (type || '?') + ']  Q ' + qtxt(q),
          '  PX ' + v[0].toFixed(2) + '  PY ' + v[1].toFixed(2),
          '  PZ ' + v[2].toFixed(2) + '  |P| ' + mag.toFixed(2),
          '  PT ' + pt.toFixed(2) + '  ETA ' + etaOf(v).toFixed(2)];
}
function updateInfo() {
  if (selEv < 0) { clearSel(); return; }
  var ev = vev[selEv], lines = [];
  var cl = selWhich === 1 ? ev.p1 : ev.p2, ct = selWhich === 1 ? ev.t1 : ev.t2, cq = selWhich === 1 ? ev.q1 : ev.q2;
  var pa = selWhich === 1 ? ev.p2 : ev.p1, pt = selWhich === 1 ? ev.t2 : ev.t1, pq = selWhich === 1 ? ev.q2 : ev.q1;
  lines.push('RUN ' + ev.run + '  EVENT ' + ev.id);
  lines.push('M(PAIR) = ' + (ev.mass !== null && isFinite(ev.mass) ? ev.mass.toFixed(3) + ' GEV' : 'N/A') +
             (ev.ss === true ? '  [SAME SIGN]' : ev.ss === false ? '  [OPPOSITE SIGN]' : ''));
  lines.push('');
  lines = lines.concat(vtxt('CLICKED MUON (WHITE)', cl, ct, cq));
  if (pa) { lines.push(''); lines = lines.concat(vtxt('PARTNER MUON (YELLOW)', pa, pt, pq)); }
  infEl.forEach(function (e, i) { e.textContent = lines[i] || ''; });
  infoBg.setAttribute('height', lines.length * 13 + 12);
  infoBg.setAttribute('display', 'inline');
  var x = (ev.mass !== null && histReady && !histGroup.getAttribute('display').match(/none/)) ? massToX(ev.mass) : null;
  if (x !== null) {
    histMarker.setAttribute('x1', x); histMarker.setAttribute('x2', x); histMarker.setAttribute('display', 'inline');
  } else histMarker.setAttribute('display', 'none');
}
function pick(e) {
  if (!vev.length) return;
  var r = svg.getBoundingClientRect();
  var mx = (e.clientX - r.left - r.width / 2) / K, my = (e.clientY - r.top - r.height / 2) / K;
  setCam();
  var sf = scaleFactor(), end = Math.min(sliceStart + MAX_SCAN, vev.length);
  var lim = (14 / K) * (14 / K), best = lim, bi = -1, bw = 1;
  for (var i = sliceStart; i < end; i++) {
    var ev = vev[i];
    for (var w = 1; w <= 2; w++) {
      var v = w === 1 ? ev.p1 : ev.p2; if (!v) continue;
      proj(v[0] * sf, v[1] * sf, v[2] * sf);
      var dx = mx - PXo, dy = my - PYo, d = dx * dx + dy * dy;
      if (d < best) { best = d; bi = i; bw = w; }
    }
  }
  selEv = bi; selWhich = bw; selDirty = true;
  updateInfo();
}
function renderSel(sf) {
  if (selEv < 0 || !scanMode) { hl1.setAttribute('display', 'none'); hl2.setAttribute('display', 'none'); return; }
  var ev = vev[selEv];
  var cl = selWhich === 1 ? ev.p1 : ev.p2, pa = selWhich === 1 ? ev.p2 : ev.p1;
  proj(0, 0, 0); var ox = PXo, oy = PYo;
  proj(cl[0] * sf, cl[1] * sf, cl[2] * sf);
  hl1.setAttribute('x1', ox); hl1.setAttribute('y1', oy); hl1.setAttribute('x2', PXo); hl1.setAttribute('y2', PYo);
  hl1.setAttribute('display', 'inline');
  if (pa) {
    proj(pa[0] * sf, pa[1] * sf, pa[2] * sf);
    hl2.setAttribute('x1', ox); hl2.setAttribute('y1', oy); hl2.setAttribute('x2', PXo); hl2.setAttribute('y2', PYo);
    hl2.setAttribute('display', 'inline');
  } else hl2.setAttribute('display', 'none');
}

/* ---------- hull / 3D object control ---------- */
/* the envelope always describes the current selection; any selection change marks it stale and
   (if it is on screen) schedules one debounced rebuild, so dragging a slider stays smooth */
function invalidateHull() {
  hullStale = true;
  if (loading) return;
  if (showHull || objOn) {
    clearTimeout(hullTimer);
    hullTimer = setTimeout(function () { withHull(function () { objDirty = true; }); }, 150);
  }
}
function withHull(cb) {
  if (HULL && !hullStale) { cb(HULL); return; }
  if (loading) { setStatus('STATUS: DATA STILL LOADING', 'TRY AGAIN WHEN LOADING FINISHES'); return; }
  if (!px.length) {
    HULL = null; objDirty = true;
    setStatus(events.length ? 'STATUS: NO EVENTS IN THE SELECTION' : 'STATUS: NO DATA',
              events.length ? 'RELAX THE SIGN, CUTS OR BIN' : 'LOAD A FILE OR PRESS DEMO DATA');
    return;
  }
  hullWaiters.push(cb);
  if (hullBusy) return;
  hullBusy = true;
  setStatus('STATUS: COMPUTING ENVELOPE...', px.length + ' VECTORS  PERCENTILE ' + (envPct >= 100 ? 'MAX' : envPct));
  setTimeout(function () {
    var ws = hullWaiters; hullWaiters = []; hullBusy = false;
    if (loading) return;
    var t0 = performance.now();
    HULL = computeEnvelope(px, py, pz, envPct);
    hullMs = performance.now() - t0;
    hullStale = false; objDirty = true;
    if (!HULL) setStatus('STATUS: ENVELOPE FAILED', 'NEED MORE EVENTS IN THE SELECTION');
    else setStatus('STATUS: ENVELOPE BUILT', HULL.nV + ' VERTICES / ' + HULL.nF + ' FACES');
    updateStats();
    ws.forEach(function (f) { f(HULL); });
  }, 30);
}
function toggleObject() {
  if (objOn) { objOn = false; syncButtons(); objDirty = true; return; }
  withHull(function (h) {
    if (!h) { syncButtons(); return; }
    objOn = true; objStart = performance.now(); objT = 0; objDirty = true; syncButtons();
    // zoom out just enough that the whole object fits on screen (never zooms in)
    targetZoom = Math.max(ZOOM_MIN, Math.min(targetZoom, 380 / Math.max(1, h.rmax * scaleFactor())));
  });
}

/* ---------- export ---------- */
function download(name, data, type) {
  var url = URL.createObjectURL(new Blob([data], { type: type }));
  var a = document.createElementNS(XHTML, 'a');
  a.href = url; a.download = name; a.style.display = 'none';
  document.documentElement.appendChild(a); a.click();
  setTimeout(function () { a.remove(); URL.revokeObjectURL(url); }, 1000);
}
function exportOBJ() {
  withHull(function (h) {
    if (!h) return;
    var s = '# OSCILLO-DETECTOR momentum-space percentile envelope, P' + h.pct + ' of the current selection (GeV for CMS open data)\n', k;
    for (k = 0; k < h.nV; k++) s += 'v ' + h.vx[k] + ' ' + h.vy[k] + ' ' + h.vz[k] + '\n';
    for (k = 0; k < h.nF; k++) s += 'f ' + (h.T[3*k] + 1) + ' ' + (h.T[3*k+1] + 1) + ' ' + (h.T[3*k+2] + 1) + '\n';
    download('momentum_envelope.obj', s, 'text/plain');
  });
}
function snapSVG() {
  // a static picture of the scene only: no script, so the saved vectors are not wiped when it is opened
  var c = svg.cloneNode(true), q;
  ['#ui', '#legend', '#histogram', '#pca-panel', '#pca-arrows', 'script', 'foreignObject'].forEach(function (sel) { q = c.querySelector(sel); if (q) q.remove(); });
  c.setAttribute('width', Math.round(W)); c.setAttribute('height', Math.round(H_));
  download('oscillo_snapshot.svg', new XMLSerializer().serializeToString(c), 'image/svg+xml');
}

/* ---------- environment ---------- */
var HEX_R = 35, GRID_R = 12, Y_PLANE = 350, hexCenters = [], HEX_A = [];
(function () {
  for (var q = -GRID_R; q <= GRID_R; q++) for (var r = -GRID_R; r <= GRID_R; r++) {
    if (Math.abs(q) + Math.abs(r) > GRID_R * 1.15) continue;
    hexCenters.push({ x: HEX_R * Math.sqrt(3) * (q + r / 2), z: HEX_R * 1.5 * r });
  }
  for (var i = 0; i < 6; i++) { var a = Math.PI / 3 * i; HEX_A.push({ c: Math.cos(a) * HEX_R, s: Math.sin(a) * HEX_R }); }
})();
function buildFloor() {
  var d = '';
  for (var h = 0; h < hexCenters.length; h++) {
    var hx = hexCenters[h].x, hz = hexCenters[h].z;
    for (var i = 0; i < 6; i++) {
      proj(hx + HEX_A[i].c, Y_PLANE, hz + HEX_A[i].s);
      d += (i ? 'L' : 'M') + PXo.toFixed(1) + ',' + PYo.toFixed(1);
    }
    d += 'Z';
  }
  hexFloor.setAttribute('d', d);
}
function buildRadar() {
  sweepAngle += 0.02;
  proj(0, Y_PLANE, 0); var x1 = PXo, y1 = PYo;
  proj(Math.cos(sweepAngle) * 800, Y_PLANE, Math.sin(sweepAngle) * 800);
  radarSweep.setAttribute('d', 'M' + x1.toFixed(1) + ',' + y1.toFixed(1) + 'L' + PXo.toFixed(1) + ',' + PYo.toFixed(1));
}

/* ---------- vector data (one path per colour bucket, never one element per event) ---------- */
function renderData(sf, stride, v0, v1) {
  var nb = colorMode === 0 ? 0 : (colorMode === 1 ? 5 : 24), bs = [], v = '', d = '', i;
  for (i = 0; i < nb; i++) bs.push('');
  if (v1 > v0) {
    proj(0, 0, 0);
    var head = 'M' + PXo.toFixed(1) + ',' + PYo.toFixed(1) + 'L';
    var which = colorMode === 1 ? bMass : bPair;
    for (i = v0; i < v1; i += stride) {
      proj(px[i] * sf, py[i] * sf, pz[i] * sf);
      if (PDo <= 10) continue;
      var X = PXo.toFixed(1), Y = PYo.toFixed(1), seg = head + X + ',' + Y;
      if (nb === 0) v += seg; else bs[which[i]] += seg;
      d += 'M' + X + ',' + Y + 'h2v2h-2Z';
    }
  }
  if (nb === 0) { vectorPath.setAttribute('d', v); vectorBloom.setAttribute('d', heavyData ? '' : v); }
  else for (i = 0; i < 24; i++) BP[i].setAttribute('d', i < nb ? bs[i] : '');
  pointPath.setAttribute('d', d);
}

/* ---------- 2D silhouette hull ---------- */
function renderHull2D(sf) {
  if (!showHull || !HULL) { hullGroup.setAttribute('display', 'none'); return; }
  var pts = [], k;
  for (k = 0; k < HULL.nV; k++) { proj(HULL.vx[k] * sf, HULL.vy[k] * sf, HULL.vz[k] * sf); if (PDo > 10) pts.push({ x: PXo, y: PYo }); }
  var hp = hull2D(pts);
  if (hp.length < 3) { hullGroup.setAttribute('display', 'none'); return; }
  hullFill.setAttribute('d', 'M' + hp.map(function (p) { return p.x.toFixed(1) + ',' + p.y.toFixed(1); }).join('L') + 'Z');
  proj(0, 0, 0);
  var o = 'M' + PXo.toFixed(1) + ',' + PYo.toFixed(1) + 'L', e = '';
  for (k = 0; k < hp.length; k++) e += o + hp[k].x.toFixed(1) + ',' + hp[k].y.toFixed(1);
  hullEdges.setAttribute('d', e);
  hullGroup.setAttribute('display', 'inline');
}

/* ---------- 3D object ---------- */
var FACE_PATHS = [], LX = -0.35, LY = -0.55, LZ = -0.76;
(function () {
  for (var k = 0; k < 8; k++) {
    var t = k / 7, p = document.createElementNS(SVGNS, 'path');
    p.setAttribute('fill', 'rgb(' + Math.round(120 * t) + ',' + Math.round(50 + 205 * t) + ',' + Math.round(60 + 175 * t) + ')');
    p.setAttribute('fill-opacity', '0.32');
    objFaces.appendChild(p); FACE_PATHS.push(p);
  }
})();
function renderObject(sf) {
  if (!objOn || !HULL) {
    objBack.setAttribute('display', 'none'); objFront.setAttribute('display', 'none'); return;
  }
  var h = HULL, m = h.nV, k;
  var tE = Math.min(1, objT / 0.65); tE = tE * tE * (3 - 2 * tE);
  var fOp = Math.max(0, Math.min(1, (objT - 0.45) / 0.55));

  for (k = 0; k < m; k++) {
    var x = h.vx[k] * sf, y = h.vy[k] * sf, z = h.vz[k] * sf;
    var y1 = y * cX - z * sX, z1 = y * sX + z * cX, x1 = x * cY - z1 * sY, z2 = x * sY + z1 * cY;
    var s = 600 / Math.max(10, z2 + camD);
    h.RX[k] = x1; h.RY[k] = y1; h.RZ[k] = z2; h.SX[k] = x1 * s; h.SY[k] = y1 * s;
    h.BAD[k] = (z2 + camD <= 10) ? 1 : 0;
  }

  var buckets = ['', '', '', '', '', '', '', ''], F = h.nF, T = h.T;
  for (k = 0; k < F; k++) {
    var a = T[3*k], b = T[3*k+1], c = T[3*k+2];
    var ux = h.RX[b]-h.RX[a], uy = h.RY[b]-h.RY[a], uz = h.RZ[b]-h.RZ[a];
    var wx = h.RX[c]-h.RX[a], wy = h.RY[c]-h.RY[a], wz = h.RZ[c]-h.RZ[a];
    var nx = uy*wz - uz*wy, ny = uz*wx - ux*wz, nz = ux*wy - uy*wx;
    var dot = -h.RX[a]*nx - h.RY[a]*ny + (-camD - h.RZ[a])*nz;
    var vis = dot > 0;
    h.fvis[k] = vis ? 1 : 0;
    if (vis && fOp > 0 && !h.BAD[a] && !h.BAD[b] && !h.BAD[c]) {
      var len = Math.sqrt(nx*nx + ny*ny + nz*nz) || 1;
      var sh = Math.max(0, (nx*LX + ny*LY + nz*LZ) / len);
      var bk = Math.min(7, Math.floor((0.15 + 0.85 * sh) * 8));
      buckets[bk] += 'M' + h.SX[a].toFixed(1) + ',' + h.SY[a].toFixed(1) + 'L' + h.SX[b].toFixed(1) + ',' + h.SY[b].toFixed(1) + 'L' + h.SX[c].toFixed(1) + ',' + h.SY[c].toFixed(1) + 'Z';
    }
  }
  for (k = 0; k < 8; k++) FACE_PATHS[k].setAttribute('d', buckets[k]);
  objFaces.setAttribute('opacity', fOp);

  var eN = Math.ceil(h.nE * tE), front = '', back = '';
  for (k = 0; k < eN; k++) {
    var ea = h.EA[k], eb = h.EB[k], f2 = h.F2[k];
    if (h.BAD[ea] || h.BAD[eb]) continue;
    var seg = 'M' + h.SX[ea].toFixed(1) + ',' + h.SY[ea].toFixed(1) + 'L' + h.SX[eb].toFixed(1) + ',' + h.SY[eb].toFixed(1);
    if (h.fvis[h.F1[k]] || (f2 >= 0 && h.fvis[f2])) front += seg; else back += seg;
  }
  objEdges.setAttribute('d', front); objBackEdges.setAttribute('d', back);

  var vN = Math.ceil(m * tE), dots = '';
  for (k = 0; k < vN; k++) {
    var vi = h.VO[k], X = h.SX[vi], Y = h.SY[vi];
    if (h.BAD[vi]) continue;
    dots += 'M' + (X - 2.5).toFixed(1) + ',' + Y.toFixed(1) + 'a2.5,2.5 0 1,0 5,0a2.5,2.5 0 1,0 -5,0';
  }
  objVerts.setAttribute('d', dots);
  objBack.setAttribute('display', 'inline'); objFront.setAttribute('display', 'inline');
}

/* ---------- single render loop ---------- */
function render(now) {
  var dragging = ptrs.size > 0;
  if (autoRotate && !dragging) rotY += 0.002;

  var zooming = false;
  if (Math.abs(zoom - targetZoom) > 0.0005 * zoom) { zoom += (targetZoom - zoom) * 0.2; zooming = true; }
  else zoom = targetZoom;

  if (objOn && objT < 1) {
    objT = Math.max(0, Math.min(1, (now - objStart) / 1600));
    objAnimating = true;
    if (objT >= 1) { objAnimating = false; objDirty = true; }
  } else objAnimating = false;

  var v0 = 0, v1 = px.length, stride = 1;
  if (scanMode && vev.length) {
    v0 = vs(sliceStart); v1 = vs(Math.min(sliceStart + MAX_SCAN, vev.length));
  } else if ((autoRotate || dragging || zooming || objAnimating) && px.length > MAX_DRAW) {
    stride = Math.ceil(px.length / MAX_DRAW);
  }
  if (stride !== lodStride) { lodStride = stride; updateStats(); }

  var key = rotX + '|' + rotY + '|' + zoom + '|' + stride + '|' + scanMode + '|' + sliceStart;
  var camChanged = key !== lastKey; lastKey = key;
  setCam();
  var sf = scaleFactor();

  if (camChanged) { buildFloor(); renderData(sf, stride, v0, v1); }
  if (!heavyData || scanMode || stride > 1 || camChanged) buildRadar();
  if (camChanged || selDirty) { renderSel(sf); selDirty = false; }
  if (camChanged || objAnimating || objDirty) {
    renderHull2D(sf); renderObject(sf); objDirty = false;
  }
  if (pcaMode && (camChanged || pcaStale)) renderPCA(sf);
  requestAnimationFrame(render);
}

buildCuts();
layout();
showLegend = (W >= 900 && H_ >= 720);
updateVisibility();
applyColorMode();
syncButtons();
updateStats();
requestAnimationFrame(render);
if (/[?&]noauto\b/.test(location.search)) setStatus('STATUS: AWAITING DATA', 'AUTO LOAD OFF: LOAD A CSV/TXT, DROP A FILE, OR PRESS DEMO DATA');
else autoLoad();
})();
